async function initTripDetails(){const e=new URLSearchParams(window.location.search).get("id");if(e)try{const t=await fetch(`/.netlify/functions/trips?t=${Date.now()}`);if(!t.ok)throw new Error("Erro ao buscar as viagens do servidor");const n=(await t.json()).find(t=>t.id===e);n?renderTrip(n):showError()}catch(e){console.error("Erro ao carregar detalhes:",e),showError()}else showError()}function renderTrip(e){document.getElementById("loading").style.display="none",document.getElementById("content").style.display="grid",document.title=`${e.title} | Amaraltour`,document.getElementById("detail-title").textContent=e.title,document.getElementById("detail-date").textContent=`📅 ${e.date}`;const t=document.getElementById("detail-image");t.src=e.image,t.alt=`Foto de ${e.title}`;const n=e.fullIntro||e.description||"";document.getElementById("detail-intro").innerHTML=n.replace(/\n/g,"<br>"),document.getElementById("detail-price").textContent=e.price||"Consulte-nos",renderList("section-boarding","detail-boarding",e.boardingInfo),renderList("section-activities","detail-activities",e.activities),renderList("section-items","detail-items",e.includedItems),renderList("payment-container","detail-payment",e.paymentInfo)}function renderList(e,t,n){const i=document.getElementById(e),o=document.getElementById(t);if(i&&o)if(o.innerHTML="",n&&""!==n.trim()){i.style.display="block";n.split("\n").forEach(e=>{if(e.trim()){const t=document.createElement("li");t.innerHTML=e.trim(),o.appendChild(t)}})}else i.style.display="none"}function showError(){document.getElementById("loading").style.display="none",document.getElementById("error-state").style.display="block"}document.addEventListener("DOMContentLoaded",initTripDetails);